-- Starter schema for Math Fun. Review/test policies with test accounts before production.
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', role text not null default 'student' check(role in ('student','teacher')), avatar_url text, theme text not null default 'rose', created_at timestamptz not null default now());
create table if not exists public.grades(id bigint generated always as identity primary key, student_id uuid not null references auth.users(id) on delete cascade, score numeric not null check(score>=0 and score<=100), note text not null default '', created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.library_files(id bigint generated always as identity primary key, owner_id uuid not null references auth.users(id) on delete cascade, title text not null, file_path text not null, mime_type text not null default '', audience text not null default 'students' check(audience in ('students','teacher')), points_awarded integer not null default 0 check(points_awarded in (0,5)), created_at timestamptz not null default now(), unique(owner_id,file_path));
create table if not exists public.chats(id bigint generated always as identity primary key, chat_type text not null check(chat_type in ('teacher','student_private','group')), title text not null default '', created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.chat_members(chat_id bigint references public.chats(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,primary key(chat_id,user_id));
create table if not exists public.messages(id bigint generated always as identity primary key,chat_id bigint not null references public.chats(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,content text not null default '',created_at timestamptz not null default now());
create table if not exists public.assignments(id bigint generated always as identity primary key,title text not null,description text not null default '',created_by uuid references auth.users(id),due_at timestamptz,created_at timestamptz not null default now());
create or replace function public.is_teacher() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='teacher'); $$;
revoke all on function public.is_teacher() from public; grant execute on function public.is_teacher() to authenticated;
-- Do not allow students to set their own role. Profile role changes should be done by trusted admin process only.
alter table public.profiles enable row level security; alter table public.grades enable row level security; alter table public.library_files enable row level security; alter table public.chats enable row level security; alter table public.chat_members enable row level security; alter table public.messages enable row level security; alter table public.assignments enable row level security;
drop policy if exists profiles_read_self_or_teacher on public.profiles; create policy profiles_read_self_or_teacher on public.profiles for select to authenticated using(id=(select auth.uid()) or (select public.is_teacher()));
drop policy if exists profiles_update_self on public.profiles; create policy profiles_update_self on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
-- IMPORTANT: profile UPDATE above needs a trigger/column-level restriction before production so students cannot update role. Do not use this schema for real student accounts until secured.
drop policy if exists grades_read_student_or_teacher on public.grades; create policy grades_read_student_or_teacher on public.grades for select to authenticated using(student_id=(select auth.uid()) or (select public.is_teacher()));
drop policy if exists grades_insert_teacher on public.grades; create policy grades_insert_teacher on public.grades for insert to authenticated with check((select public.is_teacher()) and created_by=(select auth.uid()));
drop policy if exists grades_update_teacher on public.grades; create policy grades_update_teacher on public.grades for update to authenticated using((select public.is_teacher())) with check((select public.is_teacher()));
drop policy if exists files_read_audience on public.library_files; create policy files_read_audience on public.library_files for select to authenticated using(owner_id=(select auth.uid()) or audience='students' or (select public.is_teacher()));
drop policy if exists files_insert_owner on public.library_files; create policy files_insert_owner on public.library_files for insert to authenticated with check(owner_id=(select auth.uid()) and ((select public.is_teacher()) or (points_awarded=5 and audience='students')));
drop policy if exists chats_read_member_or_teacher on public.chats; create policy chats_read_member_or_teacher on public.chats for select to authenticated using((select public.is_teacher()) or exists(select 1 from public.chat_members m where m.chat_id=chats.id and m.user_id=(select auth.uid())));
drop policy if exists members_read_self_or_teacher on public.chat_members; create policy members_read_self_or_teacher on public.chat_members for select to authenticated using(user_id=(select auth.uid()) or (select public.is_teacher()));
drop policy if exists members_manage_teacher on public.chat_members; create policy members_manage_teacher on public.chat_members for all to authenticated using((select public.is_teacher())) with check((select public.is_teacher()));
drop policy if exists messages_read_member_or_teacher on public.messages; create policy messages_read_member_or_teacher on public.messages for select to authenticated using((select public.is_teacher()) or exists(select 1 from public.chat_members m where m.chat_id=messages.chat_id and m.user_id=(select auth.uid())));
drop policy if exists messages_insert_member on public.messages; create policy messages_insert_member on public.messages for insert to authenticated with check(sender_id=(select auth.uid()) and exists(select 1 from public.chat_members m where m.chat_id=messages.chat_id and m.user_id=(select auth.uid())));
drop policy if exists assignments_read_auth on public.assignments; create policy assignments_read_auth on public.assignments for select to authenticated using(true);
drop policy if exists assignments_insert_teacher on public.assignments; create policy assignments_insert_teacher on public.assignments for insert to authenticated with check((select public.is_teacher()) and created_by=(select auth.uid()));
grant usage on schema public to authenticated;
grant select,update on public.profiles to authenticated;
grant select,insert,update on public.grades to authenticated;
grant select,insert on public.library_files to authenticated;
grant select on public.chats,public.chat_members,public.messages,public.assignments to authenticated;
grant insert on public.messages to authenticated;
-- Create Storage buckets `class-library` (private) and `avatars` (public or signed URLs) in Dashboard.
-- Storage policies must be configured separately. Do not use a public bucket for private student submissions.
-- Reward integrity note: the app UI asks for 5 points, but production must award/validate points server-side to prevent forged values.
